pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to a reasonable range for gas, but allow large values that could cause overflow
        amount = bound(amount, 1, type(uint256).max);
        vm.assume(amount > 0);

        // We need to reach a state where depositsCount + 1 overflows. 
        // We can directly send a single large ether amount, but first we may need to pre-fund the
        // contract to be able to send it. Actually, receive() is payable, so we call it with value.
        // We must deal ether to the sender.
        address sender = address(0x1234);
        vm.deal(sender, amount);

        // Record the current depositsCount before the call
        uint256 prevCount = c.depositsCount();

        // Perform the call via receive()
        bool ok;
        vm.prank(sender);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 newCount = c.depositsCount();

        // The property: if the call did not revert, then depositsCount must have increased exactly by 1.
        // If it reverted, depositsCount must be unchanged.
        // This holds for the reference because of the safe-math require guard; the mutant will have
        // depositsCount change by 1 even when it overflows, breaking the invariant when the pre-count
        // is near max and a single call causes wrap.
        if (ok) {
            assertTrue(newCount == prevCount + 1);
        } else {
            assertTrue(newCount == prevCount);
        }
    }
}

