pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to a large range that includes overflow-triggering values
        amount = bound(amount, 0, type(uint256).max);
        // Ensure the contract has sufficient balance if needed (receive doesn't require contract balance)
        vm.deal(address(this), amount);
        // Send ether via receive()
        bool ok;
        try c.receive{value: amount}() { ok = true; } catch { ok = false; }
        // For the reference contract, receive() reverts iff depositsCount + 1 would overflow.
        // Since depositsCount starts at 0, overflow occurs when amount causes depositsCount to exceed type(uint256).max - 1.
        // The rule: the call reverts exactly when depositsCount before the call + 1 overflows.
        uint256 preCount = c.depositsCount();
        bool overflow = (preCount == type(uint256).max);
        // After a non-reverting call, depositsCount increments by 1. After a reverting call, it stays the same.
        // We assert that the revert status matches the overflow condition.
        assertTrue(ok != overflow);
    }
}

