pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Admissible domain: positive deposit amounts
        vm.assume(depositAmount > 0);
        // Deposit some ether into the contract so the balance is non-zero
        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // The owner calls withdrawAll; they may also call withdraw with a fuzzed amount before or after,
        // but the invariant must hold after withdrawAll completes.
        // We let the fuzzer choose a partial withdrawal amount before the full withdrawal, constrained to not revert.
        vm.assume(withdrawAmount <= address(c).balance);
        if (withdrawAmount > 0) {
            vm.prank(c.owner());
            c.withdraw(withdrawAmount);
        }

        // Now call withdrawAll — the entry point that differs between P and M
        vm.prank(c.owner());
        c.withdrawAll();

        // Universal rule: after withdrawAll, the contract balance must be zero.
        assertEq(address(c).balance, 0, "balance must be zero after withdrawAll");
    }
}

