pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 extraBalance) public {
        // Bound to avoid overflow in addition and to keep gas reasonable
        initialBalance = bound(initialBalance, 0, 1000 ether);
        extraBalance = bound(extraBalance, 0, 1000 ether);
        // Ensure the contract has some balance to withdraw (even 0 is fine, but the property is vacuous then; let fuzzer choose)
        vm.assume(initialBalance + extraBalance >= initialBalance); // just sanity, always true

        // Fund the contract with initialBalance from owner, and extraBalance from a random address to simulate mixed sources
        address owner = c.owner();
        vm.deal(owner, initialBalance + 1 ether); // extra for gas
        vm.prank(owner);
        (bool ok,) = address(c).call{value: initialBalance}("");
        require(ok, "fund via receive failed");

        vm.deal(address(0x1), extraBalance);
        vm.prank(address(0x1));
        (ok,) = address(c).call{value: extraBalance}("");
        require(ok, "extra fund via receive failed");

        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerBalanceAfter = owner.balance;

        // General rule: the owner's balance must increase by exactly the contract's balance before the withdrawal.
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + balanceBefore);
    }
}

