import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 extraDeposits) public {
        // Restrict amounts to avoid overflow on deposit count increment, but keep domain wide.
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 1e18);
        vm.assume(extraDeposits <= 10); // keep fuzzing wide but prevent infinite loops

        // Perform initial deposits to establish state
        vm.deal(address(this), depositAmount);
        for (uint256 i = 0; i < extraDeposits; i++) {
            vm.deal(address(this), depositAmount);
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }

        // Record current depositsCount before withdrawAll
        uint256 countBefore = c.depositsCount();

        // If the contract has balance, only owner can withdraw; we set owner to this test contract.
        // The test contract is already owner because C sets owner = msg.sender in constructor.
        bool success;
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

        // The property: if withdrawAll succeeded, depositsCount must remain unchanged (no decrement).
        // The buggy version decrements before withdraw, so count changes on success.
        // The reference never changes depositsCount during withdrawAll.
        assertTrue(!success || c.depositsCount() == countBefore);
    }
}

